#!/usr/bin/env node
/**
 * Reads drizzle/meta/_journal.json and emits src/db/migrations/bundled.generated.ts
 * with Vite ?raw imports (paths relative to generated file → ../../../drizzle/*.sql?raw).
 * Run after drizzle-kit generate: npm run db:generate (postdb:generate).
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const journalPath = path.join(root, "drizzle/meta/_journal.json");
const outPath = path.join(root, "src/db/migrations/bundled.generated.ts");

const journal = JSON.parse(fs.readFileSync(journalPath, "utf8"));
const entries = journal.entries ?? [];
if (entries.length === 0) {
  console.error("No journal entries in", journalPath);
  process.exit(1);
}

const outDir = path.dirname(outPath);
const lines = [];
lines.push("/**");
lines.push(
  " * AUTO-GENERATED by scripts/generate-bundled-sql-migrations.mjs — do not edit.",
);
lines.push(
  " * Run: npm run db:bundle-sql (or postdb:generate after drizzle-kit generate).",
);
lines.push(" */");
lines.push("");

const migrationConstLines = [];
const hashPairs = [];

for (let i = 0; i < entries.length; i++) {
  const { tag, when } = entries[i];
  const sqlPath = path.join(root, "drizzle", `${tag}.sql`);
  if (!fs.existsSync(sqlPath)) {
    console.error(`Missing migration file for tag ${tag}: ${sqlPath}`);
    process.exit(1);
  }
  const query = fs.readFileSync(sqlPath, "utf8");
  const drizzleHash = crypto.createHash("sha256").update(query).digest("hex");
  const varName = `raw_${i}_${tag.replace(/[^a-zA-Z0-9_]/g, "_")}`;
  const relToSql = path.relative(outDir, sqlPath).split(path.sep).join("/");
  lines.push(`import ${varName} from "${relToSql}?raw";`);
  migrationConstLines.push(
    `  { name: ${JSON.stringify(tag)}, sql: ${varName} as string, drizzleHash: ${JSON.stringify(drizzleHash)}, when: ${Number(when)} },`,
  );
  hashPairs.push(`  ${JSON.stringify(drizzleHash)}: ${JSON.stringify(tag)},`);
}

lines.push("");
lines.push("export type BundledMigration = {");
lines.push("  name: string;");
lines.push("  sql: string;");
lines.push("  drizzleHash: string;");
lines.push("  when: number;");
lines.push("};");
lines.push("");
lines.push(
  "/** Journal order; SQL strings are inlined by Vite main bundle (?raw). */",
);
lines.push("export const BUNDLED_MIGRATIONS: BundledMigration[] = [");
lines.push(...migrationConstLines);
lines.push("];");
lines.push("");
lines.push(
  "/** Map Drizzle __drizzle_migrations.hash → migration tag for bridge. */",
);
lines.push("export const DRIZZLE_HASH_TO_NAME: Record<string, string> = {");
lines.push(...hashPairs);
lines.push("};");

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(outPath, lines.join("\n") + "\n", "utf8");
console.log("Wrote", outPath, `(${entries.length} migrations)`);
